-- Nodes of an old skill tree stored as skills, with their level (Root, Category, Subcategory) as their category. No career, job or person uses them. Children keep their own category and lose the parent link.
UPDATE skills c SET parent_skill_id = NULL WHERE parent_skill_id IN (SELECT id FROM skills WHERE category IN ('Root', 'Category', 'Subcategory')
    AND NOT EXISTS (SELECT 1 FROM occupation_skills os WHERE os.skill_id = skills.id)
    AND NOT EXISTS (SELECT 1 FROM job_skills js WHERE js.skill_id = skills.id)
    AND NOT EXISTS (SELECT 1 FROM user_skills us WHERE us.skill_id = skills.id));
DELETE FROM skills WHERE category IN ('Root', 'Category', 'Subcategory')
    AND NOT EXISTS (SELECT 1 FROM occupation_skills os WHERE os.skill_id = skills.id)
    AND NOT EXISTS (SELECT 1 FROM job_skills js WHERE js.skill_id = skills.id)
    AND NOT EXISTS (SELECT 1 FROM user_skills us WHERE us.skill_id = skills.id);

